  "upgrade.trialHistoryNote": "ለEssentials እየከፈሉ ወደ Business ከተንቀሳቀሱ፤ ተመሳሳይ የደንበኛ መለያ እና የሙከራ ታሪክ ይጠብቃሉ። Business ተጨማሪ የሰባት ቀን ሙከራ አያካትትም። የመጀመሪያ ሙከራዎ ገና እየሄደ ባለበት ወቅት ካሳደጉ፤ የመጀመሪያ ማብቂያ ቀኑ ዳግም አይዘጋጅም።",
  "upgrade.providerConfirmNote": "የዕቅድ ለውጦች ከአከፋፋይ አቅራቢ ማረጋገጫ ይፈልጋሉ። ማንኛውም የዋጋ ልዩነት፤ ተመጣጣኝ ማስተካከያ እና ተግባራዊ የሚሆንበት ቀን ለውጡን ከማጽደቅዎ በፊት መታየት አለባቸው። ማሳደግ ሁለተኛ በአንድ ጊዜ የሚሄድ ደንበኝነት ምዝገባ መፍጠር የለበትም።",
  "upgrade.chargedThroughProviderNote": "የዕቅድ ለውጦች በአከፋፋይ አቅራቢ በኩል ይከፈላሉ። ደንበኝነት ምዝገባዎን ከዚህ ገጽ በ«ደንበኝነት ምዝገባ ሰርዝ» ቁልፍ ስር ካለው አሁን ያለው ዕቅድዎ በታች በመጠቀም ወይም ከቅንብሮች መሰረዝ ይችላሉ። መሰረዝ በተከፈለበት ጊዜ መጨረሻ ላይ የወደፊት እድሳትን ያቆማል፤ መዳረሻዎን በአንድ ጊዜ በጭራሽ አያቋርጥም። ያሉት ነጻ የሥራ ቦታዎች እነዚህን አማራጮች በመመልከት አይከፈሉም።",
  "billing.cancel.title": "ደንበኝነት ምዝገባ ሰርዝ",
  "billing.cancel.description": "ከ {plan} ይውጡ። መሰረዝ በተከፈለበት ጊዜ መጨረሻ ላይ የወደፊት እድሳትን ያቆማል — መዳረሻዎን በአንድ ጊዜ በጭራሽ አያቋርጥም።",
  "billing.cancel.yourPlan": "ዕቅድዎ",
  "billing.cancel.doneTitle": "ደንበኝነት ምዝገባዎ ተሰርዟል።",
  "billing.cancel.doneWithEnd": "እስከ {endDate} ድረስ ሙሉ መዳረሻ ይጠብቃሉ። ከዚያ ቀን በኋላ የ {graceDays} ቀን ለንባብ ብቻ የጸጋ ጊዜ አለዎት — አሁንም መግባት እና ምርቶችዎን ማየት ይችላሉ፤ ነገር ግን መጨመር፤ ማርትዕ፤ መሰረዝ፤ መቃኘት፤ ማስገባት፤ ወደ ውጭ መላክ ወይም ማንኛውንም ነገር መቀየር አይችሉም። {gracePart}",
  "billing.cancel.graceEndsOn": "የ15 ቀን የጸጋ ጊዜ በ {date} ካለቀ በኋላ፤ መለያዎ እና ሁሉም መረጃዎ በቋሚነት ይሰረዛሉ፤ ሊመለሱ አይችሉም።",
  "billing.cancel.doneNoEnd": "እስከ የተከፈለበት ጊዜ መጨረሻ ድረስ ሙሉ መዳረሻ ይጠብቃሉ። ከዚያ በኋላ የ15 ቀን ለንባብ ብቻ የጸጋ ጊዜ ይተገበራል። {wipeSentence}",
  "billing.cancel.refundWindowOpen": "ከመጀመሪያ የተከፈለ ክፍያዎ በ3 ቀን ውስጥ ሰርዘዋል፤ ስለዚህ የመጀመሪያ ክፍያዎ ተመላሽ ገንዘብ ብቁ ሊሆኑ ይችላሉ። መሰረዝ ተመላሽ ገንዘቡን በራሱ አያወጣም — በ {contact} በኩል ይጠይቁ።",
  "billing.cancel.refundWindowClosed": "መሰረዝ በራሱ ተመላሽ ገንዘብ አያወጣም። ተመላሽ ገንዘብ የሚተገበረው ከመጀመሪያ የተሳካ የተከፈለ ክፍያ በ3 ቀን ውስጥ ብቻ ሲሆን በ {contact} በኩል ይጠየቃል።",
  "billing.cancel.notCanceledTitle": "ደንበኝነት ምዝገባዎ አልተሰረዘም።",
  "billing.cancel.contactCode": " {contact} ካነጋገሩ፤ ይህን ኮድ ይጥቀሱ፦ {code}",
  "billing.cancel.alreadyCanceledTitle": "ይህ ደንበኝነት ምዝገባ ቀድሞውኑ ተሰርዟል።",
  "billing.cancel.alreadyCanceledWithEnd": "በ {date} ያልቃል። እስከዚያ ድረስ ሙሉ መዳረሻ ይጠብቃሉ። ከዚያ ቀን በኋላ ምርቶችዎን ለማየት የ {graceDays} ቀን ለንባብ ብቻ የጸጋ ጊዜ አለዎት። {wipeSentence}",
  "billing.cancel.alreadyCanceledNoEnd": "በአሁኑ የተከፈለበት ጊዜ መጨረሻ ላይ ያልቃል። እስከዚያ ድረስ ሙሉ መዳረሻ ይጠብቃሉ።",
  "billing.cancel.appStoreNote": "በGoogle Play ወይም Apple App Store በኩል ከተመዘገቡ፤ በዚያ መደብር የደንበኝነት ምዝገባ ቅንብሮች በኩል መሰረዝ ሊያስፈልግዎ ይችላል። ይህ መገናኛ የመደብር ክፍያን ማቆም አይችልም። መተግበሪያውን ማራገፍ ወይም የStockHaven መለያዎን መሰረዝ የመደብር ደንበኝነት ምዝገባን አይሰርዝም።",
