  "billing.cancel.gracePeriodRest": "አሁንም መግባት እና ምርቶችዎን ማየት ይችላሉ፤ ስለዚህ የነበረዎትን ማየት እና መጻፍ ይችላሉ። ሌላው ሁሉ ተዘግቷል፦ መጨመር፤ ማርትዕ፤ መሰረዝ፤ መቃኘት፤ ማስገባት፤ ወደ ውጭ መላክ ወይም ማዛወር፤ ቅንብሮች፤ ሰራተኞች የሉም።",
