  "billing.cancelError.businessIdRequired": "የትኛውን ደንበኝነት ምዝገባ መሰረዝ እንዳለብን ማወቅ አልቻልንም። ምንም አልተለወጠም — እባክዎ እንደገና ይሞክሩ ወይም ድጋፍን ያነጋግሩ።",
