  "exports.title": "ወደ ውጪ መላክ እና ምትኬዎች",
  "exports.subtitleStart": "ማውረዶች ሁልጊዜ የተገደቡት በ",
  "exports.subtitleRest": " ብቻ ነው። እያንዳንዱ ፋይል የንግድ ስም እና የተዘጋጀበትን ቀን ይዟል።",
  "exports.createBusinessFirst": "በመጀመሪያ ንግድ ይፍጠሩ — ወደ ውጪ መላኪዎች የንግድ ናቸው፣ የመተግበሪያው አይደሉም።",
  "exports.lockedTitle": "CSV እና Excel ወደ ውጪ መላክ የBusiness ባህሪ ነው",
  "exports.lockedDesc": "የእርስዎ የሥራ ቦታ በEssentials እቅድ ላይ ነው። Business የCSV እና Excel ወደ ውጪ መላኪዎች፣ የአክሲዮን ዋጋ መገመት፣ ያልተገደቡ ምርቶች እና ሰራተኞች፣ አቅራቢዎች፣ ግዢ እና ጥቅሎች ይጨምራል።",
  "exports.seeBusiness": "Business ምን እንደሚያካትት ይመልከቱ",
  "exports.whatTheseAre": "እነዚህ ፋይሎች ምንድን ናቸው",
  "exports.about1": "እያንዳንዱ የውሂብ ስብስብ እንደ CSV ወይም እንደ እውነተኛ Excel የሥራ መጽሐፍ (.xlsx) ይመጣል — ሙሉው የእቃ ዝርዝር የሥራ መጽሐፍ Excel ብቻ ነው፣ ለእያንዳንዱ የውሂብ ስብስብ አንድ ሉህ አለው። የCSV ፋይሎች በExcel፣ Numbers፣ Google Sheets እና በአብዛኛዎቹ የአክሲዮን መተግበሪያዎች ይከፈታሉ። የUTF-8 ጽሑፍ፣ የተጠቀሱ ኮማዎች፣ በማስታወሻዎች ውስጥ ያሉ የመስመር መሰባበሮች እና በኮዶች ውስጥ ያሉ መሪ ዜሮዎች ሁሉም ይጠበቃሉ፣ እና እንደ ቀመር የሚጀምሩ ሴሎች እንደ ጽሑፍ እንዲከፈቱ ገለልተኛ ይደረጋሉ።",
  "exports.about2": "በExcel ፋይሎች ውስጥ፣ SKUዎች፣ UPCዎች፣ ISBNዎች እና ባርኮዶች የጽሑፍ ሴሎች ናቸው — በጭራሽ ሳይንሳዊ ማስታወሻ አይደሉም እና ዜሮዎችም በጭራሽ አይቆረጡም — የአምድ ስፋቶች፣ የራስጌ ማጣሪያዎች እና የገንዘብ ወይም የብዛት ቅርጸቶች ተተግብረዋል። ሙሉው የእቃ ዝርዝር የሥራ መጽሐፍ ምርቶችን፣ የአክሲዮን ደረጃዎችን፣ ቦታዎችን እና እንቅስቃሴዎችን በተለዩ ሉሆች ላይ ያቆያል።",
  "exports.about3": "በጣም ትላልቅ ወደ ውጪ መላኪዎች በእያንዳንዱ የውሂብ ስብስብ እስከ 20,000 ረድፎች ድረስ ይቆማሉ — ይህ ሲከሰት የፋይል ስም ይህንን ይገልጻል (truncated-20000)፣ ስለዚህ ከፊል ፋይል በጭራሽ እንደ ሙሉ አይተላለፍም።",
  "exports.about4": "ምትኬ የውሂብዎ ቅጽበታዊ ምስል ነው እንጂ የአንድ ጠቅታ ወደነበረበት መመለስ አይደለም። ወደነበረበት መመለስ በእጅ የሚሰራ፣ መጀመሪያ የሚገመገም ሥራ ነው፣ ስለዚህ ፋይሉን ደህንነት በተጠበቀ ቦታ ያስቀምጡት — በመተግበሪያው ውስጥ ያለ ነገር የተሰረዘ ንግድ ከእሱ ሊፈጥር አይችልም። የመተግበሪያ ኮድ እና የBase44 መድረክ ምትኬዎች ከእነዚህ ፋይሎች በተለየ ይያዛሉ።",
  "exports.about5": "ፎቶዎች እና አባሪዎች እንደ የተቀመጡ አገናኞቻቸው ይዘርዘራሉ — የምስል ፋይሎቹ ራሳቸው በማውረዱ ውስጥ አልተካተቱም።",
  "exports.backupTitle": "ሙሉ ምትኬ",
  "exports.backupDesc": "አንድ ፋይል የዚህ ንግድ ምርቶች፣ ቦታዎች፣ የአክሲዮን ደረጃዎች፣ ሙሉ የእንቅስቃሴ መዝገብ፣ አቅራቢዎች፣ ግዢ፣ ትዕዛዞች፣ መመለሻዎች፣ ቆጠራዎች እና ዝርዝሮች — እንዲሁም የመገለጫ ቅንብሮቹን ይዟል። በሚቆጣጠሩት ቦታ ያስቀምጡት።",
  "exports.backupIncludes1": "ምርቶች፣ ኮዶች፣ ወጪዎች እና ማስታወሻዎች",
  "exports.backupIncludes2": "ቦታዎች እና በእያንዳንዱ ቦታ ያሉ ብዛቶች",
  "exports.backupIncludes3": "እያንዳንዱ እንቅስቃሴ፣ ከሰሪው እና ከጊዜው ጋር",
  "exports.backupIncludes4": "ግዢ፣ ትዕዛዞች፣ መመለሻዎች እና ቆጠራዎች",
  "exports.buildingBackup": "ምትኬ እየተገነባ ነው…",
