  "print.howIntro": "ይህ መተግበሪያ ቀደም ሲል ባለዎት ማተሚያዎች ጋር ይገናኛል — እሱ ራሱ ማተሚያ አይደለም። ወደ አንዱ ለመድረስ አራት መንገዶች አሉ፣ እና መለያዎች በሁለቱም እቅዶች ላይ በየትኛውም መንገድ ይታተማሉ። የማሸጊያ ማስታወሻዎች፣ የግዢ ትዕዛዞች፣ የአቅራቢ ሰነዶች እና ሪፖርቶች ግንኙነቱ ምንም ይሁን ምን Business ብቻ ናቸው።",
  "print.howBluetoothLead": "Bluetooth።",
  "print.howBluetoothBody": "ከዚህ ገጽ፣ በዴስክቶፕ Chrome ወይም Edge እና በአንድሮይድ Chrome ላይ፤ የመለያ ማተሚያዎን ይምረጡ እና መለያዎቹ ቀጥታ ወደ እሱ ይሄዳሉ። በአይኦኤስ Safari ውስጥ አይሰራም — በአይፎን ላይ፣ የBluetooth ሕትመት በምትኩ ከሞባይል መተግበሪያው ጋር ይመጣል። Zebra ZPL ወይም የBrother የራሱን ቋንቋ ብቻ የሚናገር ማተሚያ ይህ ገጽ የሚልካቸውን መለያዎች አይረዳም፤ ይህ እንደሚሰራ ከመባሉ በፊት በእውነተኛ ማተሚያዎች ላይ ይፈተሻል።",
  "print.howWifiLead": "Wi-Fi።",
  "print.howWifiBody": "ማተሚያውን በሱቅዎ Wi-Fi ላይ ይጫኑ፣ ከዚያ የሕትመት አዝራሩን ይጠቀሙ — በዚህ ኮምፒውተር ላይ በተጫነው ማተሚያ በኩል፣ በሱቅ አውታረ መረብ ላይ ይታተማል። በአይፎን ላይ፣ AirPrint ተገንብቷል፤ በተመሳሳይ Wi-Fi ላይ ያለ የአየር ሕትመት ማተሚያ በሕትመት ሉህ ውስጥ ብቻ ይታያል፣ ገመድም መተግበሪያም አያስፈልግም፣ እና መተግበሪያው የአየር ሕትመት-ተኮር ኮድ አያስፈልገውም። ማተሚያው AirPrintን መደገፍ አለበት (አብዛኛዎቹ አዲሶቹ ይደግፋሉ) እና ስልኩና ማተሚያው በተመሳሳይ Wi-Fi ላይ መሆን አለባቸው።",
  "print.howEthernetLead": "Ethernet።",
  "print.howEthernetBody": "ማተሚያውን በኤተርኔት ገመድ ከሱቅ አውታረ መረብዎ ጋር ያገናኙ፣ በኮምፒውተሩ ላይ ይጫኑት፣ እና በሕትመት አዝራሩ በኩል ያትሙ። Ethernet የዴስክቶፕ እና የኮምፒውተር መንገድ ነው — አይፎኖች የኤተርኔት ገመዶችን አይጠቀሙም።",
  "print.howUsbLead": "USB።",
  "print.howUsbBody": "ማተሚያውን በገመዱ ወደ ኮምፒውተሩ ይሰኩት እና የሕትመት አዝራሩን ይጠቀሙ — በተጫነው ማተሚያ በኩል ይታተማል። በUSB OTG ገመድ ባለው አንድሮይድ ስልክ ላይ፣ ከላይ ያለው የUSB አዝራር ቀጥታ ከማተሚያው ጋር ይነጋገራል። አይፎኖች በUSB በቀጥታ ማተም አይችሉም — እዚያ WebUSB የለም — ስለዚህ Wi-Fi / AirPrintን ይጠቀሙ፣ ወይም Bluetoothን ከሞባይል መተግበሪያው ይጠቀሙ።",
  "print.howCordsLead": "ገመዶች አሁንም አይፎኖችን ያገለግላሉ፣ አንድ እርምጃ ተለይተው።",
  "print.howCordsBody": "በሱቅ ኮምፒውተር ላይ የተሰካ የUSB ማተሚያ፣ ወይም ከአውታረ መረቡ ጋር የተገናኘ የኤተርኔት ማተሚያ፣ በአይፎንዎ ላይ በሱቅ Wi-Fi ላይ ይታያል (AirPrint / የተጋራ ማተሚያ) — ገመዶቹ ማተሚያውን በአውታረ መረቡ ላይ በጥብቅ ያስቀምጣሉ፣ እና ስልኩ በገመድ አልባ ይደርስበታል።",
  "print.howOfflineLead": "ኢንተርኔቱ ቢቋረጥ፣",
  "print.howOfflineBody": "በዚህ ገጽ ላይ ቀደም ሲል ያሉ መለያዎች እና ሰነዶች አሁንም ይታተማሉ — የሕትመት አዝራሩ፣ የመለያዎች PDF፣ Bluetooth እና USB ግንኙነት አያስፈልጋቸውም። ኢንተርኔት የሚያስፈልገው ገጹን እና ምርቶቹን መጀመሪያ ላይ መጫን ነው። ሙሉ ከመስመር ውጪ ሁነታ (በመተግበሪያው ውስጥ ያለ ምንም ግንኙነት መሥራት) የተለየ፣ ትልቅ ግንባታ ነው እና እዚህ አይገለጽም።",
