  "settings.cancelTerms.intro": "እነዚህ ለሚከፈልባቸው የLuminous StockHaven ደንበኝነት ምዝገባዎች ውሎች ናቸው። የድረ-ገጽ ደንበኝነት ምዝገባ ክፍያ በStripe በኩል ነው። ከታች ያለውን የደንበኝነት ምዝገባ ሰርዝ ቁልፍ በመጠቀም በማንኛውም ጊዜ ደንበኝነት ምዝገባዎን እርስዎ ራስዎ መሰረዝ ይችላሉ — የሰራተኞች ማፅደቅ አያስፈልግም። የስረዛ እና የተመላሽ ገንዘብ ጥያቄዎች እንዲሁ በይፋዊ የደንበኛ ድጋፍ እውቂያ theluminousbookshop@outlook.com በኩል ሊስተናገዱ ይችላሉ።",
  "settings.cancelTerms.noApprovalBody": "በማንኛውም ጊዜ ደንበኝነት ምዝገባዎን እርስዎ ራስዎ መሰረዝ ይችላሉ። የሰራተኞች ማፅደቅ አያስፈልግም። የወደፊት እድሳት የሚቆመው የክፍያ አቅራቢው ስረዛውን ካረጋገጠ በኋላ ብቻ ነው።",
  "settings.cancelTerms.noApprovalTitle": "ያለ ማፅደቅ መሰረዝ፦",
  "settings.cancelTerms.paymentBody": "ለሚከፈልባቸው ሙከራዎች፣ የሰባት ቀን ሙከራው በሚመዘገቡበት ጊዜ የክፍያ ዘዴ ይጠይቃል። በሚመለከተው የሙከራ ስረዛ ጊዜ ገደብ ውስጥ ካልተሰረዘ በስተቀር፣ የተመረጠው ወርሃዊ ዕቅድ ከሙከራው በኋላ በራስ-ሰር ይከፈላል። ዋጋው፣ የመጀመሪያው የክፍያ ቀን እና የአቅራቢው የተለየ የስረዛ ጊዜ ገደብ በሚመዘገቡበት ጊዜ መታየት አለባቸው። የሙከራ ክፍያ በStripe በኩል ነው።",
  "settings.cancelTerms.paymentTitle": "የክፍያ ዘዴ እና አውቶማቲክ እድሳት፦",
  "settings.cancelTerms.remainingBody": "ለክፍያ ጊዜ አስቀድመው ከከፈሉ፣ እስከዚያ የተረጋገጠ የተከፈለበት ቀን ድረስ መዳረሻዎን ሊይዙ ይችላሉ። ቀደም ብሎ ማቋረጥ ተገቢ የአቅራቢ ማረጋገጫ እና ማንኛውንም የሚመለከተው የተመላሽ ገንዘብ አያያዝ ይጠይቃል። የነፃ ሙከራ መዳረሻ የሚያልቀው በአቅራቢው በተረጋገጠው የሙከራ ማብቂያ ቀን መሠረት ነው።",
  "settings.cancelTerms.remainingTitle": "የቀረ መዳረሻ፦",
  "settings.cancelTerms.storesBody": "በGoogle Play ወይም በApple App Store በኩል ከተመዘገቡ፣ ደንበኝነት ምዝገባዎ የሚከፈል እና የሚተዳደረው በዚያ መደብር ነው። ለመመዝገብ በተጠቀሙበት በተመሳሳይ የGoogle ወይም የApple መለያ የደንበኝነት ምዝገባዎች ክፍል ውስጥ በቀጥታ መሰረዝ ሊያስፈልግዎ ይችላል። የተለየ የድረ-ገጽ ደንበኝነት ምዝገባን መሰረዝ፣ ይህን መተግበሪያ ማራገፍ፣ ወይም የLuminous StockHaven መለያ መሰረዝን መጠየቅ በመደብር የሚከፈል ደንበኝነት ምዝገባን በራስ-ሰር አይሰርዝም። ማን እንደሚያስከፍልዎ ለማረጋገጥ የግዢ ደረሰኝዎን ይመልከቱ።",
  "settings.cancelTerms.storesTitle": "የGoogle Play እና የApple App Store ደንበኝነት ምዝገባዎች (በመደብር በኩል ከተመዘገቡ)፦",
  "settings.cancelTerms.title": "የስረዛ ውሎች እና ሁኔታዎች",
  "settings.cancelTerms.trialBody": "የሰባት ቀን ሙከራው ለእያንዳንዱ ብቁ ደንበኛ አንድ ጊዜ ብቻ ጥቅም ላይ ሊውል ይችላል። ሙከራን ወይም ደንበኝነት ምዝገባን መሰረዝ ሌላ ሙከራ አይሰጥም፤ ተመላሽ ደንበኞች የሚከፈልበት ደንበኝነት ምዝገባ መምረጥ አለባቸው።",
  "settings.cancelTerms.trialTitle": "አንድ ነፃ ሙከራ፦",
  "settings.canceled.endsOn": "ይህ ደንበኝነት ምዝገባ ተሰርዟል እና በ{date} ያልቃል። እስከዚያ ድረስ ሙሉ መዳረሻ ይኖርዎታል።",
  "settings.delete.checking": "ያለውን የመሰረዝ ጥያቄ በመፈተሽ ላይ…",
  "settings.delete.description": "የLuminous StockHaven መግቢያ መለያዎን ማስወገድ ይጠይቁ።",
  "settings.delete.dialogDescription": "ይህ የመለያ መሰረዝ ግምገማ ይጠይቃል። መግቢያዎን ወይም ክምችትዎን ወዲያውኑ አያስወግድም፣ እናም ማንኛውንም የStripe ደንበኝነት ምዝገባ አይሰርዝም። ጥያቄውን ለማቅረብ እንደሚፈልጉ ለማረጋገጥ {word} ይተይቡ።",
  "settings.delete.dialogTitle": "የመለያ መሰረዝ ይጠይቁ",
  "settings.delete.enterDelete": "ለማረጋገጥ {word} ያስገቡ",
  "settings.delete.exportFirst": "መዝገቦችዎን ማቆየት ከፈለጉ መጀመሪያ ክምችትዎን ወደ ውጭ ይላኩ።",
  "settings.delete.intro": "ጥያቄ ማቅረብ መለያዎን፣ ንግዶችዎን ወይም ክምችትዎን ወዲያውኑ አይሰርዝም። መሰረዝ ከመጠናቀቁ በፊት ጥያቄዎች በተናጠል ይገመገማሉ። ይህ ጥያቄ የStripe ደንበኝነት ምዝገባን አይሰርዝም ወይም የወደፊት ክፍያን አያቆምም፤ የደንበኝነት ምዝገባ ስረዛ በክፍያ አቅራቢው በኩል በተናጠል መስተናገድ አለበት።",
