  "payroll.dd.steps.body": "1. የACH ክፍያዎችን መላክ የሚችል የንግድ የባንክ መለያ ያስፈልግዎታል። 2. ከእያንዳንዱ የቡድን አባል የተፈረመ የፈቃድ ቅጽ ሰብስቡ - የተሰረዘ ቼክ ቁጥሮቹን ለማረጋገጥ ይረዳል። 3. ገንዘቡ በሰዓቱ እንዲደርስ የደመወዝ ክፍያውን ከደመወዝ ቀን ከ2-3 የስራ ቀናት በፊት ይላኩ። 4. አብዛኞቹ ክልሎች የቡድን አባሉን የጽሑፍ ስምምነት ይጠይቃሉ። ይህ መተግበሪያ ቅጾቹን ሰብስቦ በደረጃዎቹ ይመራዎታል - ገንዘቡን በእውነት መላክ የሚሆነው በራስዎ ባንክ በኩል ነው።",
