  "workforce.unscheduledNote": "ዛሬ ምንም ፈረቃ አልታቀደም፤ ስለዚህ ይህ ጊዜ ያልታቀደ ተብሎ ምልክት ይደረግበታል።",
  "workforce.inbox.help": "የሰዓት ክስተቶች፣ የዕረፍት ጊዜ መልሶች፣ ተግባሮች፣ የደመወዝ ማውጫዎች እና የመርሐ ግብር ለውጦች ለቡድንዎ፣ አዲሱ መጀመሪያ።",
  "workforce.messages.back": "ሁሉም ንግግሮች",
  "workforce.messages.empty": "እስካሁን ምንም ንግግሮች የሉም። ከላይ ባለው ቁልፍ አንዱን ጀምሩ።",
  "workforce.messages.emptyThread": "እስካሁን ምንም መልእክቶች የሉም። ለመጀመር ሰላም ይበሉ።",
  "workforce.messages.help": "ከቡድንዎ ጋር የግል አንድ ለአንድ መልእክቶች — ሌላ መተግበሪያ አያስፈልግም። ንግግሩን ማንበብ የሚችሉት በንግግሩ ውስጥ ያሉት ሁለቱ ሰዎች ብቻ ናቸው፣ እና መደብራቸውን የሚቆጣጠረው የንግድ ባለቤትም ጭምር።",
  "workforce.messages.new": "አዲስ መልእክት",
  "workforce.messages.oversight": "የባለቤት እይታ",
  "workforce.messages.oversightNote": "ይህን ንግግር ማንበብ ይችላሉ ምክንያቱም የዚህ ንግድ ባለቤት ስለሆኑ። መቀላቀል ግን አይችሉም።",
  "workforce.messages.owner": "የንግድ ባለቤት",
