  "rewards.give.help": "ሽልማቶች ወደ አንድ የቡድን አባል ይሄዳሉ። ሥራ አስኪያጆች ሰራተኞችን ይሸልማሉ፤ ባለቤቱ በቡድኑ ውስጥ ማንኛውንም ሰው መሸለም ይችላል።",
