  "workforce.tab.rewards": "ሽልማቶች",
  "training.lessons.mgr-give-rewards.step1": "የሰራተኞች አስተዳደርን ይክፈቱ እና ሽልማቶችን ይንኩ። የቡድን አባሉን ይምረጡ፣ ከዚያ ዓይነቱን፦ በመደብር ውስጥ የቅናሽ በመቶኛ፣ የስጦታ ካርድ፣ ወይም በራስዎ ቃላት የሚገልጹት ሌላ ነገር።",
  "training.lessons.mgr-give-rewards.step2": "ለሽልማቱ አጭር ስም እና ከፈለጉ ማስታወሻ ይስጡ። ሰውዬው ወዲያውኑ ደወል ያገኛል፣ እና ሽልማቱ በራሱ ኮድ በሽልማቶቼ ውስጥ ይጠብቃል።",
  "training.lessons.mgr-give-rewards.step3": "ወሰኑ፣ በንድፍ፦ ሰራተኞችን ብቻ ይሸልማሉ። ራስዎን ወይም ሌላ ሥራ አስኪያጅ መሸለም አይችሉም — ሥራ አስኪያጅን መሸለም የባለቤቱ ውሳኔ ነው፣ እና መተግበሪያው በግልጽ እምቢ ይለዋል።",
  "training.lessons.mgr-give-rewards.step4": "በካሽ ማሽኑ ላይ የቡድን አባሉ የሚያሳይዎትን ኮድ ይተይቡ እና እንደተጠቀመ ምልክት ያድርጉ — እያንዳንዱ ኮድ አንዴ ይሰራል። ዕቅዶች ቢቀየሩ የሰጡትን ሽልማት መሰረዝ ይችላሉ፤ የባለቤቱ ስጦታዎች የባለቤቱ ናቸው የሚሰርዛቸው።",
  "training.lessons.mgr-give-rewards.title": "ለሰራተኞችዎ ሽልማቶች መስጠት",
  "training.lessons.owner-give-rewards.step1": "ሽልማቶች በሰራተኞች አስተዳደር ውስጥ፣ በሽልማቶች ትር ላይ ይኖራሉ፣ እና የBusiness ዕቅድ ብቻ ናቸው — በEssentials ላይ ትሩ የተቆለፈ በር ያሳያል፤ ስለዚህ ቡድንዎ ትልቁ ዕቅድ ምን እንዳለው ማየት ይችላል።",
  "training.lessons.owner-give-rewards.step2": "በቡድኑ ውስጥ ማንኛውንም ሰው መሸለም ይችላሉ — ሰራተኞችን እና ሥራ አስኪያጆችን እኩል። ሰውዬውን ይምረጡ፣ ከዚያ ዓይነቱን፦ በመደብር ውስጥ የቅናሽ በመቶኛ (የሚመርጡት ማንኛውም በመቶኛ)፣ ወደ የትኛውም ቦታ የስጦታ ካርድ፣ ወይም በራስዎ ቃላት የሚገልጹት ማንኛውም ማበረታቻ።",
  "training.lessons.owner-give-rewards.step3": "ሽልማቱ በራሱ የአንድ ጊዜ ኮድ ይደርሳል እና የሰውዬውን ደወል ያሰማል። ኮዱን በካሽ ማሽኑ ላይ ያሳያሉ፤ ባለቤት ወይም ሥራ አስኪያጅ እንደተጠቀመ ምልክት ለማድረግ ያስገባዋል።",
  "training.lessons.owner-give-rewards.step4": "የታተመ ወይም የተጋራ የሽልማት ደረሰኝ የሚይዘው የንግድዎን ስም ብቻ ነው — የመተግበሪያውን መቼም አይደለም። የመደብርዎ ምስጋና ነው፣ ማስታወቂያ አይደለም።",
  "training.lessons.owner-give-rewards.title": "ሽልማቶች መስጠት (የBusiness ዕቅድ)",
  "training.lessons.owner-rewards-oversight.step1": "ሥራ አስኪያጅዎም ሽልማቶች መስጠት ይችላል — ለሰራተኞች ብቻ። ሥራ አስኪያጅ ራሱን ወይም ሌላ ሥራ አስኪያጅ ቢሸልም መተግበሪያው እምቢ ይለዋል፤ ሥራ አስኪያጅን መሸለም ሁልጊዜ የእርስዎ ውሳኔ ነው።",
  "training.lessons.owner-rewards-oversight.step2": "በንግዱ ውስጥ ያለ እያንዳንዱን ሽልማት በሽልማት ታሪክ ውስጥ ያያሉ፦ ማን ሰጠው፣ ማን አገኘው፣ እና ዝግጁ፣ ጥቅም ላይ የዋለ ወይም ተሰርዟል። ሥራ አስኪያጅ የሚያየው የሰጣቸውን እና የተቀበላቸውን ሽልማቶች ብቻ ነው።",
  "training.lessons.owner-rewards-oversight.step3": "ሥራ አስኪያጅዎ የሰጠውን ጨምሮ ማንኛውንም ሽልማት መሰረዝ ይችላሉ። ሥራ አስኪያጅ የራሱን ስጦታዎች መሰረዝ ይችላል፣ ግን የእርስዎን መቼም አይደለም።",
  "training.lessons.owner-rewards-oversight.step4": "እያንዳንዱ ኮድ በትክክል አንዴ ይሰራል፣ እና የተሰረዘ ሽልማት መቼም ሊጠቀም አይችልም — ታሪኩ ሁልጊዜ ሽልማት እንዴት እንዳለቀ ያሳያል።",
  "training.lessons.owner-rewards-oversight.title": "ሽልማቶችን መቆጣጠር፦ የሥራ አስኪያጅዎ መስጠት",
  "training.lessons.staff-your-rewards.step1": "ሥራ አስኪያጅዎ ወይም ባለቤቱ ሽልማት ሲሰጥዎት ደወልዎ ይጮሃል። የሰራተኞች አስተዳደርን ይክፈቱ እና በሽልማቶቼ ስር ለማየት ሽልማቶችን ይንኩ።",
  "training.lessons.staff-your-rewards.step2": "እያንዳንዱ ሽልማት የራሱ ኮድ አለው። ለራስዎ ያቆዩት — በካሽ ማሽኑ ላይ ኮዱን የሚያሳየው ሽልማቱን የሚጠቀመው ነው።",
  "training.lessons.staff-your-rewards.step3": "ለመጠቀም ሲገዙ ኮዱን ያሳዩ። በካሽ ማሽኑ ላይ ያለው ሰው ያስገባዋል እና እንደተጠቀመ ምልክት ያደርጋል — እያንዳንዱ ኮድ በትክክል አንዴ ይሰራል።",
  "training.lessons.staff-your-rewards.step4": "ሽልማቶች የBusiness ዕቅድ ደስታ ናቸው። መደብርዎ በBusiness ላይ ካልሆነ የሽልማቶች ትር በምትኩ የተቆለፈ በር ያሳያል — ያ ዕቅዱ ነው፣ ስህተት አይደለም።",
  "training.lessons.staff-your-rewards.title": "ሽልማቶችዎ፦ ኮድዎን ማግኘት እና መጠቀም",
